@* Step progress indicator showing all 5 steps *@

<div class="step-indicator d-flex align-items-center justify-content-between mb-4 px-2">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i + 1;
        var isCompleted = CompletedSteps.Contains(step);
        var isCurrent = step == CurrentStep;
        var isClickable = isCompleted && !isCurrent;

        <div class="step-item text-center @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "")"
             role="button"
             @onclick="() => { if (isClickable) OnStepClicked.InvokeAsync(step); }"
             style="cursor: @(isClickable ? "pointer" : "default"); opacity: @(!isCurrent && !isCompleted ? "0.4" : "1"); flex: 1;">
            <div class="step-circle mx-auto d-flex align-items-center justify-content-center rounded-circle mb-1
                        @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted border")"
                 style="width: 36px; height: 36px; font-size: 0.9rem;">
                @if (isCompleted && !isCurrent)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@step</span>
                }
            </div>
            <small class="d-none d-md-block @(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")">
                @StepNames[i]
            </small>
        </div>

        @if (i < StepNames.Length - 1)
        {
            <div class="flex-grow-1 mx-1" style="height: 2px; align-self: flex-start; margin-top: 18px;">
                <div style="height: 100%; background-color: @(isCompleted ? "#198754" : "#dee2e6");"></div>
            </div>
        }
    }
</div>

@code {
    private static readonly string[] StepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

